  router.patch('/workbooks/:id', (req, res) => {
    const body = asObject(req.body ?? {});
    res.json(renameWorkbook(db, req.params.id, body.name));
  });

  // 5. Bulk cell writes (cell edit and paste share this endpoint).
  router.put('/workbooks/:id/worksheets/:wid/cells', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const changes = parseCellChanges(req.body);

