 * selections are written through the contract endpoints and survive a refresh.
 */
export function WorkbookEditor() {
  const { id = '' } = useParams<{ id: string }>();
  const [snapshot, setSnapshot] = useState<WorkbookSnapshot | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [selectionByWorksheet, setSelectionByWorksheet] = useState<Record<string, SelectionRect>>(
    {},
  );
  const [editing, setEditing] = useState<CellCoord | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setLoadError(null);
    api
      .getWorkbook(id)
      .then((loaded) => {
        if (cancelled) return;
        setSnapshot(loaded);
        setSelectionByWorksheet(
          Object.fromEntries(
            loaded.worksheets.map((worksheet) => [
              worksheet.id,
              worksheet.lastSelection ?? A1_SELECTION,
            ]),
          ),
        );
        setLoading(false);
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setLoadError(messageOf(error));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const worksheets = snapshot?.worksheets ?? [];
  const activeWorksheet =
    worksheets.find((worksheet) => worksheet.isActive) ?? worksheets[0] ?? null;
  const activeWorksheetId = activeWorksheet?.id ?? '';
  const selection = selectionByWorksheet[activeWorksheetId] ?? A1_SELECTION;

  const cells = useMemo(() => {
    const map = new Map<string, string>();
    for (const [row, col, raw] of activeWorksheet?.cells ?? []) {
      map.set(cellKey(row, col), raw);
    }
    return map;
  }, [activeWorksheet]);

  // Single display-value seam (D-A8): the grid and the CSV export read the same
  // function, so sub-issue C only has to replace `worksheetDisplayValues`.
  const displayValue = useMemo(
    () => (activeWorksheet ? worksheetDisplayValues(activeWorksheet) : () => ''),
    [activeWorksheet],
  );

  // Refs keep the memoized grid callbacks stable while still reading the
  // latest worksheet/cell state.
  const activeWorksheetIdRef = useRef(activeWorksheetId);
  activeWorksheetIdRef.current = activeWorksheetId;
  const worksheetsRef = useRef<WorksheetSnapshot[]>(worksheets);
  worksheetsRef.current = worksheets;
  const cellsRef = useRef(cells);
  cellsRef.current = cells;

  const applyCellLocally = useCallback((worksheetId: string, changes: CellChange[]) => {
    setSnapshot((previous) => {
      if (!previous) return previous;
      return {
        ...previous,
        worksheets: previous.worksheets.map((worksheet) => {
          if (worksheet.id !== worksheetId) return worksheet;
          const map = new Map<string, string>();
          for (const [row, col, raw] of worksheet.cells) {
            map.set(cellKey(row, col), raw);
          }
          for (const change of changes) {
            const key = cellKey(change.row, change.col);
            if (change.raw === '') map.delete(key);
            else map.set(key, change.raw);
          }
          const cellsAfter: CellEntry[] = [...map.entries()].map(([key, raw]) => {
            const [row, col] = key.split(':').map(Number);
            return [row, col, raw];
          });
          return { ...worksheet, cells: cellsAfter };
        }),
      };
    });
  }, []);

  const commitCell = useCallback(
    async (coord: CellCoord, raw: string) => {
      setEditing(null);
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      const key = cellKey(coord.row, coord.col);
      const previousValue = cellsRef.current.get(key) ?? '';
      if (previousValue === raw) return;

      applyCellLocally(worksheetId, [{ row: coord.row, col: coord.col, raw }]);
      try {
        const result = await api.putCells(id, worksheetId, [
          { row: coord.row, col: coord.col, raw },
        ]);
        setSnapshot((previous) => (previous ? { ...previous, updatedAt: result.updatedAt } : previous));
        setErrorMessage(null);
      } catch (error: unknown) {
        applyCellLocally(worksheetId, [{ row: coord.row, col: coord.col, raw: previousValue }]);
        setErrorMessage(messageOf(error));
      }
    },
    [id, applyCellLocally],
  );

  const handleSelectionChange = useCallback(
    (next: SelectionRect, persist: boolean) => {
      const worksheetId = activeWorksheetIdRef.current;
      if (!worksheetId) return;
      setSelectionByWorksheet((previous) => {
        const current = previous[worksheetId];
        if (current && sameSelection(current, next)) return previous;
        return { ...previous, [worksheetId]: next };
      });
      if (persist) {
        api.putSelection(id, worksheetId, next).catch((error: unknown) => {
          setErrorMessage(messageOf(error));
        });
      }
    },
    [id],
  );

  const handleSelectWorksheet = useCallback(
    async (worksheetId: string) => {
      setEditing(null);
      const target = worksheetsRef.current.find((worksheet) => worksheet.id === worksheetId);
      if (!target || target.isActive) return;
      const previousActiveId =
        worksheetsRef.current.find((worksheet) => worksheet.isActive)?.id ?? worksheetId;
      const markActive = (isActiveId: string) => {
        setSnapshot((previous) =>
          previous
            ? {
                ...previous,
                worksheets: previous.worksheets.map((worksheet) => ({
                  ...worksheet,
                  isActive: worksheet.id === isActiveId,
                })),
              }
            : previous,
        );
      };
      markActive(worksheetId);
      try {
        const result = await api.patchWorksheet(id, worksheetId, { isActive: true });
        markActive(worksheetId);
        setSnapshot((previous) =>
          previous ? { ...previous, updatedAt: result.updatedAt } : previous,
        );
        setErrorMessage(null);
      } catch (error: unknown) {
        markActive(previousActiveId);
        setErrorMessage(messageOf(error));
      }
    },
    [id],
  );

  const handleRenamed = useCallback((name: string, updatedAt: string) => {
    setSnapshot((previous) => (previous ? { ...previous, name, updatedAt } : previous));
  }, []);

  const handleStartEdit = useCallback((coord: CellCoord) => {
    setEditing({ row: coord.row, col: coord.col });
  }, []);

  const handleCommitEdit = useCallback(
    (coord: CellCoord, raw: string) => {
      void commitCell(coord, raw);
    },
    [commitCell],
  );

  const handleCancelEdit = useCallback(() => {
    setEditing(null);
  }, []);

  if (loading) {
    return <div className="p-8 text-sm text-sheet-muted">Loading workbook…</div>;
  }

  if (loadError || !snapshot || !activeWorksheet) {
    return (
      <div className="mx-auto max-w-2xl p-8">
        <ErrorBanner message={loadError ?? 'Workbook not found'} />
        <Link to="/" className="text-sm text-sheet-accent underline">
          Back to workbooks
        </Link>
      </div>
    );
  }

  const anchorCell: CellCoord = { row: selection.r1, col: selection.c1 };
  const selectedRaw = cells.get(cellKey(anchorCell.row, anchorCell.col)) ?? '';

  return (
    <div className="flex h-screen flex-col bg-white">
      <header className="flex flex-wrap items-baseline gap-x-4 gap-y-1 border-b-1 border-sheet-border px-3 py-2">
        <h1 className="text-lg font-medium text-sheet-text">{snapshot.name}</h1>
        <p id={LAST_UPDATED_LABEL_ID} className="text-xs text-sheet-muted">
          {lastUpdatedText(snapshot.updatedAt)}
        </p>
      </header>

      {/* Toolbar: workbook lifecycle controls; follow-up sub-issues append here. */}
      <div
        role="toolbar"
        aria-label="Toolbar"
        className="flex h-9 items-center gap-1 border-b-1 border-sheet-border bg-sheet-header px-2"
      >
        <WorkbookToolbar
          workbookId={id}
          workbookName={snapshot.name}
          worksheet={activeWorksheet}
          displayValue={displayValue}
          onRenamed={handleRenamed}
        />
      </div>

      <FormulaBar
        coordinate={toCoordinate(anchorCell.row, anchorCell.col)}
        value={selectedRaw}
        onCommit={(value) => {
          void commitCell(anchorCell, value);
        }}
      />

      <ErrorBanner message={errorMessage} onDismiss={() => setErrorMessage(null)} />

      <div
        id="worksheet-grid-panel"
        role="tabpanel"
        aria-labelledby={`worksheet-tab-${activeWorksheetId}`}
        className="min-h-0 flex-1"
      >
        <Grid
          rowCount={activeWorksheet.rowCount}
          colCount={activeWorksheet.colCount}
          cells={cells}
          displayValue={displayValue}
          selection={selection}
          editing={editing}
          onSelectionChange={handleSelectionChange}
          onStartEdit={handleStartEdit}
          onCommitEdit={handleCommitEdit}
          onCancelEdit={handleCancelEdit}
        />
      </div>

      <WorksheetTabs
        worksheets={worksheets}
        activeWorksheetId={activeWorksheetId}
        onSelect={(worksheetId) => {
          void handleSelectWorksheet(worksheetId);
        }}
      />
    </div>
  );
}

import { useState } from 'react';
import type { WorksheetSnapshot } from '../../../shared/types';
import type { CellDisplayValue } from '../lib/cellDisplay';
import { csvFileName, downloadCsv, worksheetToCsv } from '../lib/csvExport';
import { RenameWorkbookDialog } from './RenameWorkbookDialog';

export interface WorkbookToolbarProps {
  workbookId: string;
  workbookName: string;
  /** The active worksheet; export reads only this one (REQ-1-3-2). */
  worksheet: WorksheetSnapshot;
  /** Shared display-value seam (D-A8): the export must match what the grid shows. */
  displayValue: CellDisplayValue;
  onRenamed: (name: string, updatedAt: string) => void;
}

/**
 * Editor toolbar hosting the workbook-lifecycle controls
 * (Issue #3 decision D-A10). Follow-up sub-issues append their own controls
 * here instead of editing the editor shell.
 */
export function WorkbookToolbar({
  workbookId,
  workbookName,
  worksheet,
  displayValue,
  onRenamed,
}: WorkbookToolbarProps) {
  const [renaming, setRenaming] = useState(false);

  const exportCsv = () => {
    // Pure client-side export: no request, so `updatedAt` and every piece of
    // persisted state (active worksheet, filter view, selection) stay as they are.
    const csv = worksheetToCsv(worksheet, displayValue);
    downloadCsv(csvFileName(workbookName), csv);
  };

  return (
    <>
      <button type="button" className="sheet-button" onClick={() => setRenaming(true)}>
        Rename workbook
      </button>
      <button type="button" className="sheet-button" onClick={exportCsv}>
        Export CSV
      </button>
      {renaming ? (
        <RenameWorkbookDialog
          workbookId={workbookId}
          currentName={workbookName}
          onClose={() => setRenaming(false)}
          onRenamed={onRenamed}
        />
      ) : null}
    </>
  );
}

describe('POST /api/workbooks/import', () => {
  it('creates a workbook named after the file and imports every row and column', async () => {
    const app = appFor(freshDb());
    const res = await request(app)
      .post('/api/workbooks/import')
      .send({ fileName: 'Sales Report.CSV', csv: '地区,销售额\n华东,1200\nNorth,800' });
    expect(res.status).toBe(201);
    expect(res.body.name).toBe('Sales Report');
    expect(res.body.worksheets).toHaveLength(1);
    const sheet = res.body.worksheets[0];
    expect(sheet).toMatchObject({ name: 'Sheet1', isActive: true });
    expect(sheet.lastSelection).toMatchObject({ r1: 0, c1: 0, r2: 0, c2: 0 });
    expect(sheet.cells).toEqual([
      [0, 0, '地区'],
      [0, 1, '销售额'],
      [1, 0, '华东'],
      [1, 1, '1200'],
      [2, 0, 'North'],
      [2, 1, '800'],
    ]);

    const list = await request(app).get('/api/workbooks');
    expect(list.body.map((/** @type {{ name: string }} */ w) => w.name)).toContain('Sales Report');

    const snapshot = await request(app).get(`/api/workbooks/${res.body.id}`);
    expect(snapshot.body.worksheets[0].cells).toEqual(sheet.cells);
  });

  it('imports quoted commas, escaped quotes, in-field newlines and empty fields', async () => {
    const app = appFor(freshDb());
    const csv = 'a,"b,c","d""e","f\ng"\n1,,"","x"\n';
    const res = await request(app).post('/api/workbooks/import').send({ fileName: 'tricky.csv', csv });
    expect(res.status).toBe(201);
    // `raw === ''` is not persisted (same convention as every write path).
    expect(res.body.worksheets[0].cells).toEqual([
      [0, 0, 'a'],
      [0, 1, 'b,c'],
      [0, 2, 'd"e'],
      [0, 3, 'f\ng'],
      [1, 0, '1'],
      [1, 3, 'x'],
    ]);
  });

  it('keeps the default 6x26 structure for empty and small CSVs', async () => {
    const app = appFor(freshDb());
    const empty = await request(app)
      .post('/api/workbooks/import')
      .send({ fileName: 'empty.csv', csv: '' });
    expect(empty.status).toBe(201);
    expect(empty.body.worksheets[0]).toMatchObject({ rowCount: 6, colCount: 26, cells: [] });

    const small = await request(app)
      .post('/api/workbooks/import')
      .send({ fileName: 'small.csv', csv: 'a,b\nc,d' });
    expect(small.body.worksheets[0]).toMatchObject({ rowCount: 6, colCount: 26 });
    expect(small.body.worksheets[0].cells).toEqual([
      [0, 0, 'a'],
      [0, 1, 'b'],
      [1, 0, 'c'],
      [1, 1, 'd'],
    ]);
  });

  it('grows the structure when the CSV is larger than the default', async () => {
    const app = appFor(freshDb());
    const rows = Array.from({ length: 10 }, (_unused, row) =>
      Array.from({ length: 30 }, (_unusedCol, col) => `r${row}c${col}`).join(','),
    );
    const res = await request(app)
      .post('/api/workbooks/import')
      .send({ fileName: 'big.csv', csv: rows.join('\n') });
    expect(res.status).toBe(201);
    expect(res.body.worksheets[0]).toMatchObject({ rowCount: 10, colCount: 30 });
    expect(res.body.worksheets[0].cells).toHaveLength(300);
  });

  it('falls back to the default name when the file name has nothing left after .csv', async () => {
    const app = appFor(freshDb());
    const res = await request(app).post('/api/workbooks/import').send({ fileName: '.csv', csv: 'a' });
    expect(res.status).toBe(201);
    expect(res.body.name).toBe('Untitled spreadsheet');
  });

  it('allows two workbooks with the same name', async () => {
    const app = appFor(freshDb());
    await request(app).post('/api/workbooks/import').send({ fileName: 'dup.csv', csv: 'a' });
    const second = await request(app).post('/api/workbooks/import').send({ fileName: 'dup.csv', csv: 'b' });
    expect(second.status).toBe(201);
    const list = await request(app).get('/api/workbooks');
    expect(list.body.filter((/** @type {{ name: string }} */ w) => w.name === 'dup')).toHaveLength(2);
  });

  it('rejects invalid CSV with the exact message and persists nothing', async () => {
    const db = freshDb();
    const app = appFor(db);
    const workbooks = countRows(db, 'workbooks');
    const worksheets = countRows(db, 'worksheets');
    const cells = countRows(db, 'cells');

    const res = await request(app)
      .post('/api/workbooks/import')
      .send({ fileName: 'broken.csv', csv: 'a,b\n"unterminated,c' });
    expect(res.status).toBe(400);
    expect(res.body).toEqual({
      error: { code: 'INVALID_CSV', message: 'Invalid CSV file format. Import failed.' },
    });

    expect(countRows(db, 'workbooks')).toBe(workbooks);
    expect(countRows(db, 'worksheets')).toBe(worksheets);
    expect(countRows(db, 'cells')).toBe(cells);
    const list = await request(app).get('/api/workbooks');
    expect(list.body.map((/** @type {{ name: string }} */ w) => w.name)).not.toContain('broken');
  });

  it('validates the request body shape with the uniform error format', async () => {
    const app = appFor(freshDb());
    const missingName = await request(app).post('/api/workbooks/import').send({ csv: 'a' });
    expect(missingName.status).toBe(400);
    expect(missingName.body.error.code).toBe('INVALID_BODY');
    expect(missingName.body.error.message).toBe('fileName must be a string');

    const missingCsv = await request(app).post('/api/workbooks/import').send({ fileName: 'a.csv' });
    expect(missingCsv.status).toBe(400);
    expect(missingCsv.body.error.message).toBe('csv must be a string');

    const notAnObject = await request(app).post('/api/workbooks/import').send([1, 2]);
    expect(notAnObject.status).toBe(400);
    expect(notAnObject.body.error.code).toBe('INVALID_BODY');
  });
});

