      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({
        rowCount: 4,
        colCount: 3,
        cells: [
          [0, 0, 'Changed'],
          [4, 0, 'Beyond the reported structure'],
        ],
      });
    expect(res.status).toBe(400);
    expect(res.body.error.code).toBe('INVALID_BODY');

    // The whole import rolled back: cell values and structure are untouched.
    const snapshot = await request(app).get(`/api/workbooks/${SEED_WORKBOOK_ID}`);
    const sheet1 = snapshot.body.worksheets[0];
    expect(sheet1.rowCount).toBe(6);
    expect(sheet1.cells).toContainEqual([0, 0, 'Region']);
  });
});

