// Trailing blank lines (`a\n\n`, `\n`) are line noise, not records; a blank
// line is a record holding exactly one empty field.
while (records.length > 0) {
  const last = records[records.length - 1];
  if (last.length === 1 && last[0] === '') records.pop();
  else break;
}

// Ragged records are right-padded to the widest record (contract v1.3 A-1):
// a short row means "the remaining fields are empty", never a parse error.
const columns = csvColumnCount(records);
for (const parsed of records) {
  while (parsed.length < columns) parsed.push('');
}

return records;

