  const minRows = payload.minRows === undefined ? structure.min_rows : payload.minRows;
  const minCols = payload.minCols === undefined ? structure.min_cols : payload.minCols;
  if (minRows !== null && (!Number.isInteger(minRows) || minRows < 0)) {
    throw invalidBody('minRows must be a non-negative integer or null');
