describe('PUT /api/workbooks/:id/worksheets/:wid/state', () => {
  it('replaces the worksheet state atomically', async () => {
    const app = appFor(freshDb());
    const res = await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({
        cells: [
          [0, 0, 'Only'],
          [1, 1, ''],
        ],
        rowCount: 42,
        colCount: 7,
        lastSelection: { r1: 4, c1: 1, r2: 4, c2: 1, anchor: { row: 4, col: 1 } },
      });
    expect(res.status).toBe(200);
    expect(res.body.worksheet.rowCount).toBe(42);
    expect(res.body.worksheet.colCount).toBe(7);
    expect(res.body.worksheet.cells).toEqual([[0, 0, 'Only']]);
    expect(res.body.worksheet.lastSelection).toMatchObject({ r1: 4, c1: 1 });
  });

  it('rejects a snapshot whose cells exceed the reported structure (no silent growth)', async () => {
    const res = await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({
        rowCount: 4,
        colCount: 3,
        cells: [
          [0, 0, 'Changed'],
          [4, 0, 'Beyond the reported structure'],
        ],
      });
    expect(res.status).toBe(400);
    expect(res.body.error.code).toBe('INVALID_BODY');

    // The whole import rolled back: cell values and structure are untouched.
    const snapshot = await request(app).get(`/api/workbooks/${SEED_WORKBOOK_ID}`);
    const sheet1 = snapshot.body.worksheets[0];
    expect(sheet1.rowCount).toBe(6);
    expect(sheet1.cells).toContainEqual([0, 0, 'Region']);
  });

  it('treats an absent import footprint as unchanged and null as cleared', async () => {
    const app = appFor(freshDb());
    const state = (body) =>
      request(app).put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`).send(body);

    const set = await state({ minRows: 2, minCols: 3 });
    expect(set.status).toBe(200);
    expect(set.body.worksheet).toMatchObject({ minRows: 2, minCols: 3 });

    // `undefined` = keep the current value: replaying an older snapshot (or any
    // payload that never mentions the footprint) must not erase it.
    const replay = await state({ cells: [[0, 0, 'Only']] });
    expect(replay.status).toBe(200);
    expect(replay.body.worksheet).toMatchObject({ minRows: 2, minCols: 3 });

    const snapshot = await request(app).get(`/api/workbooks/${SEED_WORKBOOK_ID}`);
    expect(snapshot.body.worksheets[0]).toMatchObject({ minRows: 2, minCols: 3 });

    const cleared = await state({ minRows: null, minCols: null });
    expect(cleared.status).toBe(200);
    expect(cleared.body.worksheet).toMatchObject({ minRows: null, minCols: null });
  });

  it('rejects an import footprint that exceeds the reported structure and rolls back', async () => {
    const app = appFor(freshDb());
    const res = await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({ rowCount: 4, colCount: 3, minRows: 5, minCols: 3 });
    expect(res.status).toBe(400);
    expect(res.body.error.code).toBe('INVALID_BODY');

    const snapshot = await request(app).get(`/api/workbooks/${SEED_WORKBOOK_ID}`);
    expect(snapshot.body.worksheets[0]).toMatchObject({ rowCount: 6, minRows: null });
  });
});

