import { describe, expect, it } from 'vitest';
import type { WorksheetSnapshot } from '../../../shared/types';
import { worksheetDisplayValues } from './cellDisplay';

function sheet(cells: [number, number, string][]): WorksheetSnapshot {
  return {
    id: 'ws-1',
    name: 'Sheet1',
    position: 0,
    isActive: true,
    rowCount: 6,
    colCount: 26,
    cells,
    lastSelection: null,
    validations: [],
    filters: [],
    pivots: [],
  };
}

/**
 * D-A8 / contract increment A-3: interim identity seam. Sub-issue C replaces the
 * implementation; these assertions describe the pre-C behaviour the acceptance
 * suite pins in the meantime (a formula cell shows and exports its raw text).
 */
=== csvExport.test 60-160 ===
    // records are separated by `\n` and no terminator is appended after the last one.
    expect(csv).toBe('Region,Sales,Status\nEast,1200,Open\nNorth,800,Closed\nSouth,700,Open');
    expect(csv.endsWith('\n')).toBe(false);
    expect(csv).not.toContain('\r');
    expect(csv.charCodeAt(0)).not.toBe(0xfeff);
  });

  it('trims trailing all-empty rows and columns but keeps gaps inside the used range', () => {
    // A1 and C3 are filled: the box is A1:C3, B2 stays an empty field.
    const csv = worksheetToCsv(
      sheet([
        [0, 0, 'a'],
        [2, 2, 'c'],
      ]),
    );
    expect(csv).toBe('a,,\n,,\n,,c');
  });

  it('exports an empty string for a worksheet with no content', () => {
    expect(worksheetToCsv(sheet([]))).toBe('');
    // Explicit empty cells (`raw === ''`) are not content.
    expect(worksheetToCsv(sheet([[0, 0, '']]))).toBe('');
  });

  it('escapes in place without changing row/column order', () => {
    const csv = worksheetToCsv(
      sheet([
        [0, 0, 'comma,value'],
        [0, 1, 'quote"value'],
        [0, 2, 'line\nbreak'],
      ]),
    );
    expect(csv).toBe('"comma,value","quote""value","line\nbreak"');
  });

  it('keeps an empty field inside the used range even when it is the last cell of a row', () => {
    const csv = worksheetToCsv(
      sheet([
        [0, 0, 'a'],
        [1, 2, 'c'],
      ]),
    );
    expect(csv).toBe('a,,\n,,c');
  });

  it('exports the value produced by the injected display seam', () => {
    // D-A8: the export never reads the raw text directly. Sub-issue C replaces
    // the seam with the formula engine, which is what makes a formula cell
    // export its calculated result instead of its expression.
    const worksheet = sheet([
      [0, 0, '=1+1'],
      [0, 1, 'plain'],
    ]);
    const csv = worksheetToCsv(worksheet, (row, col) => (row === 0 && col === 0 ? '2' : 'plain'));
    expect(csv).toBe('2,plain');
  });
});

describe('csvFileName', () => {
  it('suggests a name ending in .csv', () => {
    expect(csvFileName('Q3 Sales')).toBe('Q3 Sales.csv');
    expect(csvFileName('  预算  ')).toBe('预算.csv');
  });

  it('does not double an existing .csv extension', () => {
    expect(csvFileName('report.csv')).toBe('report.csv');
    expect(csvFileName('report.CSV')).toBe('report.CSV');
  });

  it('falls back to a usable base name', () => {
    expect(csvFileName('   ')).toBe('workbook.csv');
  });
});

