it('exports an empty string for a worksheet with no content and no import footprint', () => {
  expect(worksheetToCsv(sheet([]))).toBe('');
  // Explicit empty cells (`raw === ''`) are not content.
  expect(worksheetToCsv(sheet([[0, 0, '']]))).toBe('');
});

it('honours the import footprint so trailing empty fields survive a round trip', () => {
  // Contract v1.3 / A-4: `a,b\nc,d,` parses to 2 x 3 (ragged padding), so the
  // import records minRows=2/minCols=3 and the export keeps the third field
  // even though it lies outside the non-empty bounding box (2 x 2).
  const csv = worksheetToCsv(
    sheet(
      [
        [0, 0, 'a'],
        [0, 1, 'b'],
        [1, 0, 'c'],
        [1, 1, 'd'],
      ],
      6,
      26,
      { minRows: 2, minCols: 3 },
    ),
  );
  expect(csv).toBe('a,b,\nc,d,');
});

it('uses max(used range, footprint) and never shrinks below the footprint', () => {
  // Content wider than the footprint: the bounding box wins on that axis.
  const wide = worksheetToCsv(
    sheet([[0, 0, 'a'], [0, 3, 'd']], 6, 26, { minRows: 2, minCols: 1 }),
  );
  expect(wide).toBe('a,,,d\n,,,');
});

it('exports the footprint empty fields when every cell was cleared (footprint wins)', () => {
  // Contract v1.3 §4: "no content -> empty file" only when bounding box and
  // footprint are both empty; a live footprint still exports its empty fields.
  expect(worksheetToCsv(sheet([], 6, 26, { minRows: 2, minCols: 3 }))).toBe(',,\n,,');
});

