import fs from 'node:fs';
import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';

/**
 * Sub-issue A acceptance suite (REQ-1-2-1 / 1-2-2 / 1-3-1 / 1-3-2).
 *
 * Runs against the production shape (built frontend served by the backend on
 * one port, throwaway SQLite file) via `bash checks/run-e2e.sh`, and drives the
 * UI exclusively through accessible names, per Issue #1 contract §5.
 *
 * Self-contained: every workbook this suite works with is created through the
 * UI, so it never depends on edits made by `smoke.spec.ts` to the seeded
 * `Q3 Sales` workbook.
 */

const SEED_LINK = { name: 'Q3 Sales', exact: true } as const;

/** Wait until the home page has loaded its list. */
async function gotoHome(page: Page) {
  await page.goto('/');
  await expect(page.getByRole('link', SEED_LINK)).toBeVisible();
}

/** Create a workbook through the UI and return to its editor. */
async function createWorkbook(page: Page, name: string) {
  await gotoHome(page);
  await page.getByRole('button', { name: 'New blank workbook' }).click();
  await expect(page).toHaveURL(/\/new$/);
  await page.getByLabel('Workbook name').fill(name);
  await page.getByRole('button', { name: 'Create' }).click();
  await expect(page).toHaveURL(/\/workbook\/.+/);
}

/** Upload a CSV through the home-page dialog and wait for the editor. */
async function importCsv(page: Page, fileName: string, csv: string) {
  await gotoHome(page);
  await page.getByRole('button', { name: 'Import CSV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Import CSV' });
  await expect(dialog).toBeVisible();
  await page.getByLabel('CSV file').setInputFiles({
    name: fileName,
    mimeType: 'text/csv',
    buffer: Buffer.from(csv, 'utf8'),
  });
  await page.getByRole('button', { name: 'Confirm import' }).click();
  await expect(page).toHaveURL(/\/workbook\/.+/);
}

/** Export the active worksheet and return the suggested name plus text content. */
async function exportCsv(page: Page): Promise<{ fileName: string; csv: string }> {
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.getByRole('button', { name: 'Export CSV' }).click(),
  ]);
  const path = await download.path();
  if (!path) throw new Error('download has no local path');
  return { fileName: download.suggestedFilename(), csv: fs.readFileSync(path, 'utf8') };
}

async function cellText(page: Page, coordinate: string): Promise<string> {
  return (await page.getByRole('gridcell', { name: coordinate, exact: true }).textContent()) ?? '';
}

/**
 * Compare a cell's exact text content. `toHaveText` normalizes whitespace, and
 * in-field newlines are part of what this suite must verify, so it compares the
 * raw `textContent` instead.
 */
async function expectCellText(page: Page, coordinate: string, text: string): Promise<void> {
  const actual = await cellText(page, coordinate);
  expect(
    actual,
    `gridcell ${coordinate} should contain ${JSON.stringify(text)} but contained ${JSON.stringify(actual)}`,
  ).toBe(text);
}

