if (payload.minRows !== undefined || payload.minCols !== undefined) {
  // Import footprint (contract v1.3 / increment A-4, Issue #1 comments #51
  // and #57): a static lower bound for the CSV export's used range.
  // `undefined`/`null` means "not declared" - the same convention as
  // rowCount/colCount and lastSelection - so replaying an older snapshot
  // cannot silently erase a footprint; a declared value is persisted.
  //
  // The invariant `min <= reported structure` is implemented here for now.
  // Contract v1.3 §2 assigns the shared validation helper to sub-issue B's
  // PR #9 (`assertWorksheetStateValid`, published in Issue #1 comment #66),
  // and PR #8 switches to consuming it once it lands in develop. Error
  // messages below already match that helper verbatim so the switch is
  // behaviour-preserving.
  const structure = /** @type {{ row_count: number, col_count: number, min_rows: number | null, min_cols: number | null }} */ (
    db
      .prepare('SELECT row_count, col_count, min_rows, min_cols FROM worksheets WHERE id = ?')
      .get(ws.id)
  );
  const declaredMinRows = payload.minRows ?? null;
  const declaredMinCols = payload.minCols ?? null;
  if (declaredMinRows !== null && (!Number.isInteger(declaredMinRows) || declaredMinRows < 0)) {
    throw invalidBody('minRows must be a non-negative integer');
  }
  if (declaredMinCols !== null && (!Number.isInteger(declaredMinCols) || declaredMinCols < 0)) {
    throw invalidBody('minCols must be a non-negative integer');
  }
  if (declaredMinRows !== null && declaredMinRows > structure.row_count) {
    throw invalidBody(
      `minRows must not exceed the reported structure (${structure.row_count})`,
    );
  }
  if (declaredMinCols !== null && declaredMinCols > structure.col_count) {
    throw invalidBody(
      `minCols must not exceed the reported structure (${structure.col_count})`,
    );
  }
  db.prepare('UPDATE worksheets SET min_rows = ?, min_cols = ? WHERE id = ?').run(
    declaredMinRows ?? structure.min_rows ?? 0,
    declaredMinCols ?? structure.min_cols ?? 0,
    ws.id,
  );
}

