it('treats an absent or null import footprint as unchanged', async () => {
  const app = appFor(freshDb());
  const state = (body) =>
    request(app).put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`).send(body);

  const set = await state({ minRows: 2, minCols: 3 });
  expect(set.status).toBe(200);
  expect(set.body.worksheet).toMatchObject({ minRows: 2, minCols: 3 });

  // `undefined`/`null` = not declared: replaying an older snapshot (or any
  // payload that never mentions the footprint) must not erase it.
  const replay = await state({ cells: [[0, 0, 'Only']] });
  expect(replay.status).toBe(200);
  expect(replay.body.worksheet).toMatchObject({ minRows: 2, minCols: 3 });

  const explicitNull = await state({ minRows: null, minCols: null });
  expect(explicitNull.status).toBe(200);
  expect(explicitNull.body.worksheet).toMatchObject({ minRows: 2, minCols: 3 });

  const snapshot = await request(app).get(`/api/workbooks/${SEED_WORKBOOK_ID}`);
  expect(snapshot.body.worksheets[0]).toMatchObject({ minRows: 2, minCols: 3 });

  // 0 = no footprint (the blank-workbook value).
  const cleared = await state({ minRows: 0, minCols: 0 });
  expect(cleared.status).toBe(200);
  expect(cleared.body.worksheet).toMatchObject({ minRows: 0, minCols: 0 });
});

it('rejects an import footprint that exceeds the reported structure and rolls back', async () => {
  const app = appFor(freshDb());
  const res = await request(app)
    .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
    .send({ rowCount: 4, colCount: 3, minRows: 5, minCols: 3 });
  expect(res.status).toBe(400);
  expect(res.body.error.code).toBe('INVALID_BODY');
  // Messages mirror sub-issue B's shared helper (Issue #1 comment #66).
  expect(res.body.error.message).toBe('minRows must not exceed the reported structure (4)');

  const snapshot = await request(app).get(`/api/workbooks/${SEED_WORKBOOK_ID}`);
  // The whole import rolled back, including the row/column change.
  expect(snapshot.body.worksheets[0]).toMatchObject({ rowCount: 6, minRows: 0 });
});

