describe('migrations', () => {
  it('are repeatable and create the contract tables', () => {
    const db = openDatabase(':memory:');
    migrate(db);
    migrate(db);
    const tables = /** @type {{ name: string }[]} */ (
      db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all()
    ).map((r) => r.name);
    for (const table of [
      'workbooks',
      'worksheets',
      'cells',
      'validation_rules',
      'filters',
      'pivots',
      'schema_migrations',
    ]) {
      expect(tables).toContain(table);
    }
    expect(countRows(db, 'schema_migrations')).toBe(1);
  });
});

describe('seed', () => {
  it('is idempotent across restarts', () => {
    const db = freshDb();
    seedDatabase(db);
    seedDatabase(db);
    expect(countRows(db, 'workbooks')).toBe(1);
