import { useEffect, useState } from 'react';

export interface FormulaBarProps {
  /** A1-style coordinate of the selected cell. */
  coordinate: string;
  /** Raw content of the selected cell (formula text stays raw). */
  value: string;
  onCommit: (value: string) => void;
}

/**
 * Name box + formula bar. The text box is labelled exactly "Formula bar"
 * (contract §3) and stays in two-way sync with the selected cell: committing
 * here writes through the same cells endpoint the grid uses.
 */
export function FormulaBar({ coordinate, value, onCommit }: FormulaBarProps) {
  const [draft, setDraft] = useState(value);

  useEffect(() => {
    setDraft(value);
  }, [value, coordinate]);

  const commit = () => {
    if (draft !== value) onCommit(draft);
  };

  return (
    <div className="flex items-stretch border-b-1 border-sheet-border bg-white">
      <input
        readOnly
        aria-label="Name box"
        value={coordinate}
        className="w-24 shrink-0 border-r-1 border-sheet-border bg-white px-2 py-1 text-center text-sm text-sheet-text outline-none"
      />
      <div className="flex w-8 shrink-0 items-center justify-center border-r-1 border-sheet-border text-sm italic text-sheet-muted">
        fx
      </div>
      <input
        aria-label="Formula bar"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Enter') {
            event.preventDefault();
            commit();
          } else if (event.key === 'Escape') {
            event.preventDefault();
            setDraft(value);
          }
        }}
        onBlur={commit}
        className="h-8 w-full min-w-0 flex-1 px-2 text-sm text-sheet-text outline-none"
      />
    </div>
  );
}

